from fractions import Fraction
from itertools import combinations
from math import comb
from typing import List, Sequence


def expected_empty_exact(p: Sequence[Fraction], j: int) -> Fraction:
    n = len(p)
    total = Fraction(0)
    for i in range(n):
        competitors = [k for k in range(n) if k != i]
        for r in range(len(competitors) + 1):
            for subset in combinations(competitors, r):
                q_s = sum((p[s] for s in subset), Fraction(0))
                total += Fraction((-1) ** r) * (p[i] / (p[i] + q_s)) ** j
    return total


def sweep_simplex_3(j: int, steps: int = 12) -> None:
    """Sweep the 3-type simplex and report the maximizer."""
    unif = [Fraction(1, 3)] * 3
    best_val = expected_empty_exact(unif, j)
    best_at = "uniform"
    n_below = 0
    n_total = 0
    for i in range(1, steps):
        for k in range(1, steps - i):
            a = Fraction(i, steps)
            b = Fraction(k, steps)
            c = Fraction(1) - a - b
            if c <= 0:
                continue
            val = expected_empty_exact([a, b, c], j)
            n_total += 1
            if val < best_val:
                n_below += 1
            if val > best_val:
                best_val, best_at = val, f"({a},{b},{c})"
    print(f"j={j}: uniform value = {float(expected_empty_exact(unif, j)):.6f}")
    print(f"       maximizer = {best_at}, max value = {float(best_val):.6f}")
    print(f"       {n_below}/{n_total} sampled interior points strictly below uniform")


if __name__ == "__main__":
    for j in (2, 3, 4):
        sweep_simplex_3(j)

