function EXPECTED_EMPTY_EXACT(p[1..N], j):
    total <- 0
    for i in 1..N:
        competitors <- {1..N} \ {i}
        for each subset S of competitors:
            q_S <- sum of p[s] for s in S
            ratio <- p[i] / (p[i] + q_S)
            total <- total + (-1)^|S| * ratio^j
    return total   // exact rational value of E_p[U_j^N]

function EXPECTED_EMPTY_UNIFORM(N, j):
    total <- 0
    for s in 0..N-1:
        total <- total + (-1)^s * C(N-1, s) / (1+s)^j
    return N * total   // exact E_unif[U_j^N]

