function EXPECTED_EMPTY_MONTE_CARLO(p[1..N], j, trials):
    total_empty <- 0
    repeat trials times:
        counts <- array of N zeros; seen <- 0
        while seen < N:
            t <- sample index from distribution p
            if counts[t] == 0: seen <- seen + 1
            counts[t] <- counts[t] + 1
        total_empty <- total_empty + #{ t : counts[t] < j }
    return total_empty / trials
